INSERT INTO learning_drills(id,unit_id,title,status,target_count,questions,created_at) VALUES('foundation-count','unit-foundation-count','数とたし算・基礎確認','published','5','[{"id":"q-0","text":"2 + 1 はいくつですか？","choices":["3","4","2","6"],"answer":0,"points":1,"category":"数とたし算","explanation":"2個と1個を合わせると3個です。","hint1":"数を合わせる意味を確認します。","hint2":"りんごが2個あり、3個もらうと、2+3=5個です。","skillIds":["foundation-count"]},{"id":"q-1","text":"3 + 2 はいくつですか？","choices":["6","4","8","5"],"answer":3,"points":1,"category":"数とたし算","explanation":"3個と2個を合わせると5個です。","hint1":"数を合わせる意味を確認します。","hint2":"りんごが2個あり、3個もらうと、2+3=5個です。","skillIds":["foundation-count"]},{"id":"q-2","text":"4 + 3 はいくつですか？","choices":["6","10","7","8"],"answer":2,"points":1,"category":"数とたし算","explanation":"4個と3個を合わせると7個です。","hint1":"数を合わせる意味を確認します。","hint2":"りんごが2個あり、3個もらうと、2+3=5個です。","skillIds":["foundation-count"]},{"id":"q-3","text":"5 + 4 はいくつですか？","choices":["12","9","10","8"],"answer":1,"points":1,"category":"数とたし算","explanation":"5個と4個を合わせると9個です。","hint1":"数を合わせる意味を確認します。","hint2":"りんごが2個あり、3個もらうと、2+3=5個です。","skillIds":["foundation-count"]},{"id":"q-4","text":"6 + 5 はいくつですか？","choices":["11","12","10","14"],"answer":0,"points":1,"category":"数とたし算","explanation":"6個と5個を合わせると11個です。","hint1":"数を合わせる意味を確認します。","hint2":"りんごが2個あり、3個もらうと、2+3=5個です。","skillIds":["foundation-count"]}]','2026-09-13T00:00:00.000Z');
