INSERT INTO learning_drills(id,unit_id,title,status,target_count,questions,created_at) VALUES('foundation-subtract','unit-foundation-subtract','ひき算・基礎確認','published','5','[{"id":"q-0","text":"5 − 1 はいくつですか？","choices":["4","5","3","7"],"answer":0,"points":1,"category":"ひき算","explanation":"5個から1個取ると4個残ります。","hint1":"残りや違いを求めます。","hint2":"5個から2個取ると、5−2=3個です。","skillIds":["foundation-subtract"]},{"id":"q-1","text":"6 − 2 はいくつですか？","choices":["5","3","7","4"],"answer":3,"points":1,"category":"ひき算","explanation":"6個から2個取ると4個残ります。","hint1":"残りや違いを求めます。","hint2":"5個から2個取ると、5−2=3個です。","skillIds":["foundation-subtract"]},{"id":"q-2","text":"7 − 3 はいくつですか？","choices":["3","7","4","5"],"answer":2,"points":1,"category":"ひき算","explanation":"7個から3個取ると4個残ります。","hint1":"残りや違いを求めます。","hint2":"5個から2個取ると、5−2=3個です。","skillIds":["foundation-subtract"]},{"id":"q-3","text":"8 − 4 はいくつですか？","choices":["7","4","5","3"],"answer":1,"points":1,"category":"ひき算","explanation":"8個から4個取ると4個残ります。","hint1":"残りや違いを求めます。","hint2":"5個から2個取ると、5−2=3個です。","skillIds":["foundation-subtract"]},{"id":"q-4","text":"9 − 5 はいくつですか？","choices":["4","5","3","7"],"answer":0,"points":1,"category":"ひき算","explanation":"9個から5個取ると4個残ります。","hint1":"残りや違いを求めます。","hint2":"5個から2個取ると、5−2=3個です。","skillIds":["foundation-subtract"]}]','2026-09-13T00:00:00.000Z');
