INSERT INTO learning_drills(id,unit_id,title,status,target_count,questions,created_at) VALUES('foundation-negative','unit-foundation-negative','負の数と数直線・基礎確認','published','5','[{"id":"q-0","text":"0から数直線を左へ2進んだ数はいくつですか？","choices":["-2","-1","-3","1"],"answer":0,"points":1,"category":"負の数と数直線","explanation":"左は負の方向なので、答えは-2です。","hint1":"0より小さい数を数直線で考えます。","hint2":"0から左へ3進むと−3。−3より右にある−1の方が大きい数です。","skillIds":["foundation-negative"]},{"id":"q-1","text":"0から数直線を左へ3進んだ数はいくつですか？","choices":["-2","-4","0","-3"],"answer":3,"points":1,"category":"負の数と数直線","explanation":"左は負の方向なので、答えは-3です。","hint1":"0より小さい数を数直線で考えます。","hint2":"0から左へ3進むと−3。−3より右にある−1の方が大きい数です。","skillIds":["foundation-negative"]},{"id":"q-2","text":"0から数直線を左へ4進んだ数はいくつですか？","choices":["-5","-1","-4","-3"],"answer":2,"points":1,"category":"負の数と数直線","explanation":"左は負の方向なので、答えは-4です。","hint1":"0より小さい数を数直線で考えます。","hint2":"0から左へ3進むと−3。−3より右にある−1の方が大きい数です。","skillIds":["foundation-negative"]},{"id":"q-3","text":"0から数直線を左へ5進んだ数はいくつですか？","choices":["-2","-5","-4","-6"],"answer":1,"points":1,"category":"負の数と数直線","explanation":"左は負の方向なので、答えは-5です。","hint1":"0より小さい数を数直線で考えます。","hint2":"0から左へ3進むと−3。−3より右にある−1の方が大きい数です。","skillIds":["foundation-negative"]},{"id":"q-4","text":"0から数直線を左へ6進んだ数はいくつですか？","choices":["-6","-5","-7","-3"],"answer":0,"points":1,"category":"負の数と数直線","explanation":"左は負の方向なので、答えは-6です。","hint1":"0より小さい数を数直線で考えます。","hint2":"0から左へ3進むと−3。−3より右にある−1の方が大きい数です。","skillIds":["foundation-negative"]}]','2026-09-13T00:00:00.000Z');
