INSERT INTO learning_drills(id,unit_id,title,status,target_count,questions,created_at) VALUES('foundation-signed','unit-foundation-signed','正負の数の加減・基礎確認','published','5','[{"id":"q-0","text":"−2 + 6 を計算してください。","choices":["4","5","3","7"],"answer":0,"points":1,"category":"正負の数の加減","explanation":"−2から右へ6進むので4です。","hint1":"正と負の数を足したり引いたりします。","hint2":"−2+5は、−2から右へ5進むので3。−2−(−5)も−2+5=3です。","skillIds":["foundation-signed"]},{"id":"q-1","text":"−3 + 7 を計算してください。","choices":["5","3","7","4"],"answer":3,"points":1,"category":"正負の数の加減","explanation":"−3から右へ7進むので4です。","hint1":"正と負の数を足したり引いたりします。","hint2":"−2+5は、−2から右へ5進むので3。−2−(−5)も−2+5=3です。","skillIds":["foundation-signed"]},{"id":"q-2","text":"−4 + 8 を計算してください。","choices":["3","7","4","5"],"answer":2,"points":1,"category":"正負の数の加減","explanation":"−4から右へ8進むので4です。","hint1":"正と負の数を足したり引いたりします。","hint2":"−2+5は、−2から右へ5進むので3。−2−(−5)も−2+5=3です。","skillIds":["foundation-signed"]},{"id":"q-3","text":"−5 + 9 を計算してください。","choices":["7","4","5","3"],"answer":1,"points":1,"category":"正負の数の加減","explanation":"−5から右へ9進むので4です。","hint1":"正と負の数を足したり引いたりします。","hint2":"−2+5は、−2から右へ5進むので3。−2−(−5)も−2+5=3です。","skillIds":["foundation-signed"]},{"id":"q-4","text":"−6 + 10 を計算してください。","choices":["4","5","3","7"],"answer":0,"points":1,"category":"正負の数の加減","explanation":"−6から右へ10進むので4です。","hint1":"正と負の数を足したり引いたりします。","hint2":"−2+5は、−2から右へ5進むので3。−2−(−5)も−2+5=3です。","skillIds":["foundation-signed"]}]','2026-09-13T00:00:00.000Z');
