INSERT INTO learning_drills(id,unit_id,title,status,target_count,questions,created_at) VALUES('foundation-equation','unit-foundation-equation','等式と一次方程式・基礎確認','published','5','[{"id":"q-0","text":"x + 1 = 3 の x はいくつですか？","choices":["2","3","1","5"],"answer":0,"points":1,"category":"等式と一次方程式","explanation":"両辺から1を引くと x = 2 です。","hint1":"等式の両辺に同じ操作をして未知数を求めます。","hint2":"x+3=5 の両辺から3を引くと x=2 です。","skillIds":["foundation-equation"]},{"id":"q-1","text":"x + 2 = 5 の x はいくつですか？","choices":["4","2","6","3"],"answer":3,"points":1,"category":"等式と一次方程式","explanation":"両辺から2を引くと x = 3 です。","hint1":"等式の両辺に同じ操作をして未知数を求めます。","hint2":"x+3=5 の両辺から3を引くと x=2 です。","skillIds":["foundation-equation"]},{"id":"q-2","text":"x + 3 = 7 の x はいくつですか？","choices":["3","7","4","5"],"answer":2,"points":1,"category":"等式と一次方程式","explanation":"両辺から3を引くと x = 4 です。","hint1":"等式の両辺に同じ操作をして未知数を求めます。","hint2":"x+3=5 の両辺から3を引くと x=2 です。","skillIds":["foundation-equation"]},{"id":"q-3","text":"x + 4 = 9 の x はいくつですか？","choices":["8","5","6","4"],"answer":1,"points":1,"category":"等式と一次方程式","explanation":"両辺から4を引くと x = 5 です。","hint1":"等式の両辺に同じ操作をして未知数を求めます。","hint2":"x+3=5 の両辺から3を引くと x=2 です。","skillIds":["foundation-equation"]},{"id":"q-4","text":"x + 5 = 11 の x はいくつですか？","choices":["6","7","5","9"],"answer":0,"points":1,"category":"等式と一次方程式","explanation":"両辺から5を引くと x = 6 です。","hint1":"等式の両辺に同じ操作をして未知数を求めます。","hint2":"x+3=5 の両辺から3を引くと x=2 です。","skillIds":["foundation-equation"]}]','2026-09-13T00:00:00.000Z');
