CREATE TABLE ai_policy (id INTEGER PRIMARY KEY CHECK(id=1), mode TEXT NOT NULL DEFAULT 'shared' CHECK(mode IN ('shared','personal','hybrid','disabled')), daily_limit INTEGER NOT NULL DEFAULT 30, concurrency_limit INTEGER NOT NULL DEFAULT 2, max_output_tokens INTEGER NOT NULL DEFAULT 8000);
CREATE TABLE personal_ai (user_id TEXT PRIMARY KEY REFERENCES users(id), source TEXT NOT NULL DEFAULT 'shared' CHECK(source IN ('shared','personal')), endpoint TEXT NOT NULL DEFAULT 'https://api.openai.com/v1', model TEXT NOT NULL DEFAULT '', encrypted_key TEXT NOT NULL DEFAULT '');
CREATE TABLE ai_requests (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),source TEXT NOT NULL,day TEXT NOT NULL,started_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',tokens INTEGER NOT NULL DEFAULT 0);
CREATE INDEX ai_requests_limits ON ai_requests(user_id,source,day,status,started_at);
CREATE TABLE learning_skills(id TEXT PRIMARY KEY,subject TEXT NOT NULL,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',example TEXT NOT NULL DEFAULT '',foundation INTEGER NOT NULL DEFAULT 0);
CREATE TABLE skill_prerequisites(skill_id TEXT NOT NULL REFERENCES learning_skills(id),prerequisite_id TEXT NOT NULL REFERENCES learning_skills(id),PRIMARY KEY(skill_id,prerequisite_id),CHECK(skill_id!=prerequisite_id));
ALTER TABLE drill_units ADD COLUMN skill_id TEXT REFERENCES learning_skills(id);
CREATE TABLE drill_support(session_id TEXT NOT NULL REFERENCES drill_sessions(id),question_id TEXT NOT NULL,hint_level INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(session_id,question_id));
CREATE TABLE learning_returns(user_id TEXT NOT NULL REFERENCES users(id),session_id TEXT NOT NULL REFERENCES drill_sessions(id),return_session_id TEXT NOT NULL REFERENCES drill_sessions(id),PRIMARY KEY(user_id,session_id));

-- Offline foundation material; administrators can extend prerequisite relationships.
